// Idiomas: o texto-fonte do app é português; aqui ficam as traduções.
// Idioma automático pelo navegador (ex.: Tailândia → tailandês); o usuário pode trocar pelas bandeiras (EN / PT / RU).
'use strict';

const I18N = {
  // idiomas com bandeira na tela inicial
  main: [
    { code: 'en', name: 'English', flag: 'us' },
    { code: 'pt', name: 'Português', flag: 'br' },
    { code: 'ru', name: 'Русский', flag: 'ru' },
  ],
  // todos os idiomas traduzidos (os outros caem no inglês)
  all: { pt: 'pt-BR', en: 'en-US', ru: 'ru-RU', es: 'es-ES', th: 'th-TH' },
  lang: 'pt', locale: 'pt-BR',
  detect() {
    let saved = null; try { saved = JSON.parse(localStorage.getItem('ca3.lang')); } catch (e) { /* sem armazenamento */ }
    if (saved && this.all[saved]) return saved;
    for (const l of navigator.languages || [navigator.language || 'en']) {
      const c = String(l).toLowerCase().split('-')[0];
      if (this.all[c]) return c;
    }
    return 'en';
  },
  set(code) { try { localStorage.setItem('ca3.lang', JSON.stringify(code)); } catch (e) { } location.reload(); },
  init() {
    this.lang = this.detect(); this.locale = this.all[this.lang];
    document.documentElement.lang = this.locale;
    const d = I18N_DICT[this.lang] || {};
    this.exact = new Map(); this.patterns = [];
    for (const [k, v] of Object.entries(d)) {
      if (/\{\d\}/.test(k)) {
        const re = new RegExp('^' + k.replace(/[.*+?^${}()|[\]\\]/g, m => m === '{' || m === '}' ? m : '\\' + m).replace(/\{(\d)\}/g, '(.*?)') + '$', 's');
        this.patterns.push([re, k, v]);
      } else this.exact.set(k, v);
    }
    // os padrões mais longos primeiro (mais específicos)
    this.patterns.sort((a, b) => b[1].length - a[1].length);
  },
  /** Traduz um texto do app (ou devolve o original). */
  t(s) {
    if (this.lang === 'pt' || typeof s !== 'string' || !s) return s;
    const hit = this.exact.get(s); if (hit !== undefined) return hit;
    const m = s.match(/^(\s*)([\s\S]*?)(\s*)$/);
    if (m[2] !== s) { const v = this.exact.get(m[2]); if (v !== undefined) return m[1] + v + m[3]; }
    for (const [re, , v] of this.patterns) {
      const r = m[2].match(re);
      if (r) return m[1] + v.replace(/\{(\d)\}/g, (_, i) => this.t(r[+i + 1] ?? '')) + m[3];
    }
    return s;
  },
  /** Traduz os textos fixos do index.html (data-i18n). */
  page() { document.querySelectorAll('[data-i18n]').forEach(e => { e.textContent = T(e.textContent); }); },
  flagSvg(f) {
    const svg = {
      us: '<svg viewBox="0 0 30 20"><rect width="30" height="20" fill="#B22234"/><g fill="#fff">' + [1, 3, 5, 7, 9, 11].map(i => `<rect y="${i * 20 / 13}" width="30" height="${20 / 13}"/>`).join('') + '</g><rect width="13" height="10.8" fill="#3C3B6E"/></svg>',
      br: '<svg viewBox="0 0 30 20"><rect width="30" height="20" fill="#009C3B"/><path d="M15 2.5 27.5 10 15 17.5 2.5 10z" fill="#FFDF00"/><circle cx="15" cy="10" r="4.6" fill="#002776"/></svg>',
      ru: '<svg viewBox="0 0 30 20"><rect width="30" height="20" fill="#fff"/><rect y="6.67" width="30" height="6.67" fill="#0039A6"/><rect y="13.33" width="30" height="6.67" fill="#D52B1E"/></svg>',
    }[f];
    const d = document.createElement('span'); d.className = 'flag'; d.innerHTML = svg; return d;
  },
  /** Bandeiras EN / PT / RU (tela inicial). */
  picker() {
    const box = document.createElement('div'); box.className = 'lang-picker';
    for (const l of this.main) {
      const b = document.createElement('button');
      b.className = 'lang-btn' + (l.code === this.lang ? ' on' : ''); b.title = l.name; b.setAttribute('aria-label', l.name);
      b.append(this.flagSvg(l.flag), document.createTextNode(l.code.toUpperCase()));
      b.onclick = () => { if (l.code !== this.lang) this.set(l.code); };
      box.append(b);
    }
    return box;
  },
};
const T = s => I18N.t(s);

